import sys

def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    best = [-1, -1, -1]
    for ch in s:
        d = int(ch) % 3
        new = best[:]
        for r in range(3):
            if best[r] >= 0:
                nr = (r + d) % 3
                if best[r] + 1 > new[nr]:
                    new[nr] = best[r] + 1
        if ch != '0' and new[d] < 1:
            new[d] = 1
        best = new
    keep = best[0]
    if '0' in s and keep < 1:
        keep = 1
    print(-1 if keep < 1 else n - keep)

